gTk(){return"\u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629"},
gTC(){return"\u0627\u0644\u0628\u0627\u062f\u0626\u0629"},
