gOy(){return"\u0633\u064a\u0633\u062a\u062e\u062f\u0645\u0648\u0646\u0647 \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u2014 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0646\u0634\u0627\u0624\u0647\u0645 \u0628\u062f\u0648\u0646\u0647."},
gOt(){return"\u0627\u0644\u062f\u0648\u0631"},
gOx(){return"\u0641\u0631\u064a\u0642 \u0627\u0644\u0645\u0628\u064a\u0639\u0627\u062a"},
gRM(){return"\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u062d\u0633\u0627\u0628"},
gHe(){return"\u0627\u0633\u0645 \u0627\u0644\u0628\u0646\u0643 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gHc(){return"\u0631\u0642\u0645 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gHg(){return"\u0622\u064a\u0628\u0627\u0646 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gRN(){return'\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 (\u0645\u062b\u0644 "ADCB \u0627\u0644\u062c\u0627\u0631\u064a")'},
gRY(){return"\u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a"},
ga0Y(){return'\u0645\u062b\u0644 "\u0639\u0647\u062f\u0629 \u0645\u0643\u062a\u0628 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644"'},
